import{_ as a,o as t,c as e,a4 as i}from"./chunks/framework.BRzJ4ijD.js";const d=JSON.parse('{"title":"Cgroup v2、CPU 迁移与亲和","description":"","frontmatter":{},"headers":[],"relativePath":"os/sched/cgroup.md","filePath":"os/sched/cgroup.md","lastUpdated":1788475713000}'),p={name:"os/sched/cgroup.md"};function o(n,s,r,l,c,u){return t(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="cgroup-v2、cpu-迁移与亲和" tabindex="-1">Cgroup v2、CPU 迁移与亲和 <a class="header-anchor" href="#cgroup-v2、cpu-迁移与亲和" aria-label="Permalink to &quot;Cgroup v2、CPU 迁移与亲和&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>OS 调度物理硬共享 CPU, 但工程上我们需要在<strong>逻辑子单元</strong>(进程 / 容器 / 子系统)上&quot;重量计 + 资源隔离&quot;. 这就是 cgroup 出现的理由. cgroup v2 整合解决了 v1 时代几十个独立 controller 的混乱, 现代容器调度 (k8s / docker) 都基于本. 你在 K8s yaml 写 <code>resources.requests.cpu=2</code>, 你实际启的是 cgroup v2 的 <code>cpu.weight=8192</code>(或 <code>cpu.max=quota/period</code>). 这章把 cgroup 物理 + 与 OS scheduler 同一抽象.</p><h2 id="_1-cgroup-是什么" tabindex="-1">1. cgroup 是什么 <a class="header-anchor" href="#_1-cgroup-是什么" aria-label="Permalink to &quot;1. cgroup 是什么&quot;">​</a></h2><p>cgroup = control group = Linux 提供把任意 进程组 绑定到资源限制层. 资源包括: cpu / memory / IO / network / pid / freezer 等.</p><p><strong>配上 namespace (type-of 系统看到的隔离)</strong>, 它们加起来叫容器.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>namespace: 让 看到</span></span>
<span class="line"><span>cgroup:     让 用 / 减少</span></span></code></pre></div><p>这俩 abstractly 说一下&quot;same&quot; 差在: namespace 改 client 对 kernel state 的视角, cgroup 改 scheduler 给你多少.</p><h2 id="_2-cgroup-v1-vs-v2" tabindex="-1">2. cgroup v1 vs v2 <a class="header-anchor" href="#_2-cgroup-v1-vs-v2" aria-label="Permalink to &quot;2. cgroup v1 vs v2&quot;">​</a></h2><p>v1 (Linux 2.6.24-2017): 每控制器一棵独立树, 多控制器混用易出问题 (e.g. 在 cpu hierarchy 上挂 memory 子树不一致).</p><p>v2 (Linux 4.5+ unified hierarchy): 一棵树, 所有进程只在一个 cgroup, 单点 unified 一份. 控制器在 internal nodes 启用, 是 <code>+/resume</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># v2 mount</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cgroup2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> none</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 新建 cgroup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/mygroup</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $$</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/mygroup/cgroup.procs</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;max 100000 100000&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/mygroup/cpu.max</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 100ms quota / 100ms period = 1 CPU</span></span></code></pre></div><h2 id="_3-cpu-weight-cpu-max-软限-vs-硬限" tabindex="-1">3. cpu.weight / cpu.max: 软限 vs 硬限 <a class="header-anchor" href="#_3-cpu-weight-cpu-max-软限-vs-硬限" aria-label="Permalink to &quot;3. cpu.weight / cpu.max: 软限 vs 硬限&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cpu.max:   &quot;&lt;quota&gt; &lt;period&gt;&quot; hard limit. quota=200000, period=100000 ⇒ 2 CPU.</span></span>
<span class="line"><span>cpu.weight: 1-10000, CFS shares 静配比例.    软限 (guarantees 最小份额).</span></span></code></pre></div><p>工程如何选:</p><ul><li><strong>soft (weight)</strong>: 容器间可以互相 借, 没用就拿所以. 适合 K8s request.</li><li><strong>hard (max)</strong>: 不能跑超, 量化 fixed 资源. 适合 K8s limit.</li></ul><p>K8s <code>requests.cpu</code> 配 cpu.weight, <code>limits.cpu</code> 配 cpu.max. 这就是 GKE/EKS clone 在容器里 看到的 resource 分配.</p><h2 id="_4-cpu-迁移-cgroup-cpu-max" tabindex="-1">4. Cpu 迁移 + cgroup cpu.max <a class="header-anchor" href="#_4-cpu-迁移-cgroup-cpu-max" aria-label="Permalink to &quot;4. Cpu 迁移 + cgroup cpu.max&quot;">​</a></h2><p>把 task 从 cgroup A 迁 cgroup B:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/B/cgroup.procs</span></span></code></pre></div><p>迁移本质是修改 task 的 <code>cgroup-&gt;subsys[]</code> 指针; CPU 资源调整在 task tick 时重算 vruntime / weight.</p><p>cgroup CPU bandwidth control:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每次 task_tick: 递减它的 quota;</span></span>
<span class="line"><span>quota 用完 ⇒ throttled, 放入 throttled-rb, 等下一 period 重新填充 quota;</span></span>
<span class="line"><span>被 unthrottled 时回到 rq.</span></span></code></pre></div><p>实测:</p><ul><li>container cpu.max = &quot;1 1&quot; (1 ms / 1 ms) ⇒ 1 个容器节流 → 99% utilization throttled点 single cpu 的 30% 拒绝. <strong>K8s + limit CPU 偶 small 容易 掉到 throttle = P99 worst</strong>.</li><li>设 cpu.max 时尽量让 quota&gt;=100ms 以避免 catch-effect.</li></ul><h2 id="_5-memory-cgroup-oom" tabindex="-1">5. memory cgroup + OOM <a class="header-anchor" href="#_5-memory-cgroup-oom" aria-label="Permalink to &quot;5. memory cgroup + OOM&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1G</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/x/memory.max</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/x/memory.current</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 当前使用</span></span></code></pre></div><p>cgroup 内存超 memory.max 时, 触发 cgroup OOM killer:</p><ul><li>选最大 memory 的 root task, kill;</li><li>不会 panic, 不会杀其他 cgroup 任务.</li></ul><p>URL + OOM 在 container = 排查 ⇒ 位 进程 kill + 应 heap chunked events to detect restartability.</p><h2 id="_6-io-字节级-controller" tabindex="-1">6. io 字节级 controller <a class="header-anchor" href="#_6-io-字节级-controller" aria-label="Permalink to &quot;6. io 字节级 controller&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>io.max:  &quot;8:16 rbps=50000000 wbps=10000000 riops=200 wiops=200&quot;</span></span>
<span class="line"><span>        # major:minor + bytes/sec + iops/sec</span></span>
<span class="line"><span>io.weight: 1-10000 类似 cpu.weight</span></span></code></pre></div><p>cgroup v2 io controller 是 blk-mq 级; 通过 CFQ-替换 bfq-scheduler 控制 实队列.</p><blockquote><p>注意: blk 级 IO controller 在 NVMe 上 (因NVMe 不上 CFQ / BFQ) 走 <code>blk-iocost</code> (Linux 5.0+ 配置 cost model). 配置较复杂, 工业大 cluster 一般最好对 IO 加 weight priority.</p></blockquote><h2 id="_7-cgroup-pid-隔离" tabindex="-1">7. cgroup + Pid 隔离 <a class="header-anchor" href="#_7-cgroup-pid-隔离" aria-label="Permalink to &quot;7. cgroup + Pid 隔离&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo 1000 &gt; /sys/fs/cgroup/x/pids.max</span></span></code></pre></div><p>PID 数量限制, 防止容器 fork-bomb. K8s Pod <code>podPidsLimit</code> 内部走 cgroup pids.max.</p><h2 id="_8-多语言-runtime-起容器" tabindex="-1">8. 多语言 + runtime 起容器 <a class="header-anchor" href="#_8-多语言-runtime-起容器" aria-label="Permalink to &quot;8. 多语言 + runtime 起容器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语言</th><th>runtime 与 cgroup 是否协调</th><th>经验</th></tr></thead><tbody><tr><td>Java</td><td>G1 默认会看 cgroup 内存限制</td><td>JDK 11+ ( atol after 11.0.+)</td></tr><tr><td>Go runtime</td><td>GOMAXPROCS 自 1.22 看 cgroup cpu.max</td><td>修复 runtime 能 看到 quota 不 自己 be 默认 ncpu</td></tr><tr><td>Rust std</td><td>不 let火箭 std 看 cgroup 限于 runtime</td><td>必须 cgroup 静 allow</td></tr><tr><td>Python</td><td>例如 多 默认不看</td><td>因 PyPy 内 alloc 是紧 几不错的作为先夏</td></tr><tr><td>Node</td><td>V8 默认 max-oldSpace + size 4 GB</td><td>不 默认 + cgroup 需 优</td></tr></tbody></table><p>特别: <code>GOMAXPROCS=go1.22+</code> 才读 cgroup; 早期 Go 看不到 cgroup cpu quota, 你 K8s limit 1 CPU + 但 GOMAXPROCS=64 ⇒ scheduler 充分运行但 throttle 严重, 资源利用率差.</p><p>修复 runtime &quot;搞容器感度&quot; 在 2022-2024 时代逐 Gengr成 be more cost friendly 是现代 OS + language 跨层读完.</p><h2 id="_9-k8s-的-cgroup-关系" tabindex="-1">9. K8s 的 cgroup 关系 <a class="header-anchor" href="#_9-k8s-的-cgroup-关系" aria-label="Permalink to &quot;9. K8s 的 cgroup 关系&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pod / Container  ⇒  cgroup</span></span>
<span class="line"><span>requests.cpu=1   ⇒  cgroup.cpu.weight=512</span></span>
<span class="line"><span>limits.cpu=2     ⇒  cgroup.cpu.max=200000/100000</span></span>
<span class="line"><span>limits.memory=2G ⇒  cgroup.memory.max=2147483648</span></span></code></pre></div><p><strong>Pod 的 cgroup 是从父 QoS 类派生</strong>: BestEffort / Burstable / Guaranteed, K8s 通过 G 父级 cgroup resources 决定是否 OOM (Guaranteed 优先) 防止 best-effort 抢 machine.</p><h2 id="_10-这一章带走的东西" tabindex="-1">10. 这一章带走的东西 <a class="header-anchor" href="#_10-这一章带走的东西" aria-label="Permalink to &quot;10. 这一章带走的东西&quot;">​</a></h2><ul><li>cgroup v2 unified ai 主控制器 同层级, 现代 container 行;</li><li>cpu.max 是 hardlimit硬 资源命. cpu.weight 软限;</li><li>K8s limit 当小 quota + small period ⇒ potential P99 throttle 避免;</li><li>自适应工具 kubelet config + cpu + memory + io + 关注 cgroup-adapt runtime;</li><li>设 / Standalone Go 经济; K8s recomms runtime GOMAXPROCS default <code>min(ncpu, cpu.max / period)</code>.</li></ul><p>下一节 → <a href="./../lock/">锁与同步原语</a></p>`,47)])])}const g=a(p,[["render",o]]);export{d as __pageData,g as default};
